import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Card,
  Form,
  Input,
  Button,
  Alert,
  Select,
  notification,
  Spin,
  DatePicker,
  Icon
} from 'antd'
import TokopediaEndorseWrapper from './index.style'
import TokopediaEndorseActions from '../../redux/tokopediaEndorse/actions'
import IntlMessages from '../../components/utility/intlMessages'
import { injectIntl } from 'react-intl'
import queryString from 'query-string'
import Footer from '../../components/Footer/footer'
import moment from 'moment'
import validator from '../../helpers/validator'
import getAppConfig from '../../components/utility/getAppConfig'

const FormItem = Form.Item
const Option = Select.Option
const TextArea = Input.TextArea
const { resetTokopediaEndorseRedux, getFirstMediaPolicyDetails, postTokopediaEndorseRequest } = TokopediaEndorseActions
class TokopediaEndorse extends React.Component {
	state = {
	  internalID: null
	}
	componentWillReceiveProps (nextProps) {
	  const { postTokopediaEndorseLoading, postTokopediaEndorseError, postTokopediaEndorseMessage } = nextProps
	  if (!postTokopediaEndorseLoading && postTokopediaEndorseMessage) {
	    notification[
	      postTokopediaEndorseError
	        ? 'error'
	        : 'success'
	    ]({
	      message: this.intlText({
	        id: postTokopediaEndorseError
	          ? 'Error'
	          : 'disimpan'
	      }),
	      description: postTokopediaEndorseError
	        ? this.intlText({ id: postTokopediaEndorseMessage })
	        : ''
	    })
	    this.props.resetTokopediaEndorseRedux(['postTokopediaEndorseMessage'])
	  }
	}
	intlText = (messageObj = {
	  id: ' '
	}) => {
	  return this.props.intl.formatMessage(messageObj)
	}
	componentDidMount () {
	  this.props.resetTokopediaEndorseRedux()
	  const query = queryString.parse(window.location.search)
	  this.setState({ internalID: query.id })
	  this.props.getFirstMediaPolicyDetails({
	    query: {
	      id: query.id
	    }
	  })
	}
	validateSelect = (type) => {
	  if (type === 'ktp') {
	    return validator.validateIdentityKtp
	  } else if (type === 'sim') {
	    return validator.validateSIM
	  } else {
	    return false
	  }
	}
	handleSubmit = async e => {
	  e.preventDefault()
	  const { internalID } = this.state
	  const { form } = this.props
	  const payload = form.getFieldsValue()
	  form.validateFields(payload, (error, values) => {
	    if (!error) {
	      const data = {
	        'identity_type': payload.identity_type,
	        'identity_no': payload.identity_number,
	        'email': payload.email,
	        'dob': payload.dob.format('YYYY-MM-DD'),
	        'phone_no': '62-' + payload.phone_no,
	        'address': payload.address
	      }
	      this.props.postTokopediaEndorseRequest({
	        body: data,
	        params: {
	          id: internalID
	        }
	      })
	    }
	  })
	}
	disabledDate = (current) => {
	  return current > moment().subtract(17, 'years')
	}
	renderform = () => {
	  const config = {
	    rules: [
	      {
	        type: 'object',
	        required: true,
	        message: 'Please select time!'
	      }
	    ]
	  }
	  const { getFieldDecorator } = this.props.form
	  const {
	    tokopediaPolicyDetails,
	    tokopediaPolicyDetailsError,
	    postTokopediaEndorseLoading
	  } = this.props
	  return (<Form onSubmit={this.handleSubmit} id='myForm'>
  <h2>
  <IntlMessages id='Data Pelanggan' />
	    </h2>
  <p>
  <IntlMessages id='Untuk kelancaran proses administrasi, harap isi data diri Anda dengan' />&nbsp;
  <b><IntlMessages id='data terbaru' /></b>
				&nbsp;
  <IntlMessages id='secara lengkap dan jelas.' />
	    </p>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='Nomor Aplikasi' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {
	            getFieldDecorator('application_no', {
	              initialValue: tokopediaPolicyDetails.application_no || '-'
	            })(<Input disabled />)
	          }
	        </FormItem>
	      </Col>
	    </Row>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='Tipe Identitas' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {
	            getFieldDecorator('identity_type', {
	              rules: [
	                {
	                  required: true,
	                  whitespace: true,
	                  message: (<IntlMessages id='Identity type tidak boleh kosong' />)
	                }
	              ],
	              initialValue: 'ktp'
	            })(<Select >
  <Option key='ktp'>KTP</Option>
  <Option key='sim'>SIM</Option>
  <Option key='passport'>PASSPORT</Option>
  <Option key='kitas'>KITAS</Option>
	            </Select>)
	          }
	        </FormItem>
	      </Col>
	    </Row>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='Nomor Identitas' autoComplete='off' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {
	            getFieldDecorator('identity_number', {
	              rules: [
	                {
	                  required: true,
	                  whitespace: true,
	                  message: (<IntlMessages id='Nomor Identity tidak boleh kosong' />)
	                }, {
	                  validator: this.validateSelect(this.props.form.getFieldsValue()[`identity_type`])
	                }
	              ]
	            })(<Input autoComplete='off' />)
	          }
	        </FormItem>
	      </Col>
	    </Row>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='Email' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {
	            getFieldDecorator('email', {
	              rules: [
	                {
	                  required: true,
	                  type: 'email',
	                  message: (<IntlMessages id='Format email salah' />)
	                }
	              ]
	            })(<Input type='email' autoComplete='off' />)
	          }
	        </FormItem>
	      </Col>
	    </Row>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='No Handphone' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {
	            getFieldDecorator('phone_no', {
	              rules: [
	                {
	                  required: true,
	                  whitespace: true,
	                  message: (<IntlMessages id='No Handphone tidak boleh kosong' />)
	                }, {
	                  validator: validator.validateTravelokaPhone
	                }
	              ]
	            })(<Input autoComplete='off' />)
	          }
	        </FormItem>
	      </Col>
	    </Row>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='Tanggal Lahir' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {getFieldDecorator('dob', config)(<DatePicker disabledDate={this.disabledDate} />)}
	        </FormItem>
	      </Col>
	    </Row>
  <Row className='form-container'>
  <Col xs={24} sm={24} md={7} lg={7} style={{
	        marginTop: '8px'
	      }}>
  <label style={{
	          marginTop: '10px'
	        }}>
  <strong>
  <IntlMessages id='Alamat' />
	          </strong>
	        </label>
	      </Col>
  <Col xs={24} sm={24} md={17} lg={17}>
  <FormItem>
  {
	            getFieldDecorator('address', {
	              rules: [
	                {
	                  required: true,
	                  whitespace: true,
	                  message: (<IntlMessages id='Alamat tidak boleh kosong' />)
	                }
	              ]
	            })(<TextArea disabled={!!tokopediaPolicyDetailsError} autosize={{
	              minRows: 4,
	              maxRows: 8
	            }} autoComplete='off' />)
	          }
	        </FormItem>
	      </Col>
	    </Row>
  <Row>
  <Col>
  <div className='btn-form-order-container'>
  <Button disabled={!tokopediaPolicyDetails.application_no || !!postTokopediaEndorseLoading} type='primary' className='button btn-form-order' htmlType='submit' form='myForm' key='submit'>
  <IntlMessages id='SIMPAN' />
	          </Button>
	        </div>
	      </Col>
	    </Row>
	  </Form>)
	}
	render () {
	  const {
	    tokopediaPolicyDetails,
	    tokopediaPolicyDetailsLoading,
	    tokopediaPolicyDetailsError,
	    tokopediaPolicyDetailsMessage,
	    postTokopediaEndorseLoading,
	    postTokopediaEndorseError,
	    postTokopediaEndorseData
	  } = this.props
	  return (<div>
  <TokopediaEndorseWrapper BRAND_COLOR={getAppConfig('BRAND_COLOR', '#ffd500')}>
  <Row style={{
	        display: 'flex',
	        justifyContent: 'center'
	      }}>
  <Col xs={24} sm={24} md={12} lg={12} xl={12}>
  <Card className='form-cards'>
  <Spin spinning={!!tokopediaPolicyDetailsLoading || !!postTokopediaEndorseLoading} indicator={<Icon type='loading' spin />}>
  {
	                !tokopediaPolicyDetailsLoading && tokopediaPolicyDetailsError && (<Alert message='Error' description={this.intlText({
	                  id: tokopediaPolicyDetailsMessage || 'Error'
	                })} type='error' />)
	              }
  {tokopediaPolicyDetails.application_no && !(!postTokopediaEndorseLoading && !postTokopediaEndorseError && !!postTokopediaEndorseData) && (this.renderform())}
  {
	                !postTokopediaEndorseLoading && !postTokopediaEndorseError && !!postTokopediaEndorseData && (<div>
  <h2><IntlMessages id='Terima kasih!' /></h2>
  <IntlMessages id='Permintaan Anda sudah terdaftar.' />
	                </div>)
	              }
	            </Spin>
	          </Card>
	        </Col>
	      </Row>
	    </TokopediaEndorseWrapper>
  <Footer />
	  </div>)
	}
}
TokopediaEndorse.defaultProps = {
  tokopediaPolicyDetails: {}
}

const TokopediaEndorseWrapped = Form.create()(TokopediaEndorse)
export default connect(state => ({
  tokopediaPolicyDetails: state.TokopediaEndorse.tokopediaPolicyDetails,
  tokopediaPolicyDetailsMessage: state.TokopediaEndorse.tokopediaPolicyDetailsMessage,
  tokopediaPolicyDetailsLoading: state.Loading.GET_TOKOPEDIA_POLICY_DETAILS,
  tokopediaPolicyDetailsError: state.Error.GET_TOKOPEDIA_POLICY_DETAILS,
  postTokopediaEndorseMessage: state.TokopediaEndorse.postTokopediaEndorseMessage,
  postTokopediaEndorseData: state.TokopediaEndorse.postTokopediaEndorseData,
  postTokopediaEndorseLoading: state.Loading.POST_TOKOPEDIA_ENDORSE,
  postTokopediaEndorseError: state.Error.POST_TOKOPEDIA_ENDORSE
}), { getFirstMediaPolicyDetails, postTokopediaEndorseRequest, resetTokopediaEndorseRedux })(injectIntl(TokopediaEndorseWrapped))
